// ===== Real-photo spiders: several small spiders wandering at random (cut from your sample image, animated with IK) =====
// Add to index.html after script.js:  <script src="spider.js"></script>   (nothing else to upload)
(() => {
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  // ---------- SETTINGS (change these) ----------
  const COUNT = 6;          // how many spiders (2 to 4 looks good)
  const SIZE = 0.20;         // overall size: 1 = big, 0.5 = small, 0.35 = tiny
  const DEPTH = true;       // true = each spider slowly drifts a little nearer / farther, false = fixed size
  // ---------------------------------------------

  const ATLAS = new Image(); ATLAS.src = 'data:image/png;base64,';
  const BODY = {"ax":63,"ay":70,"w":110,"h":182,"r":[0,0,110,182]};
  const LEGS = [{"side":1,"i":0,"fl":57.3,"dl":206.4,"fh":26,"dh":41.0,"pad":8,"rootU":25,"rootV":27,"restU":239.2,"restV":70.7,"f":[589,268,73,52],"d":[0,184,222,82]},{"side":1,"i":1,"fl":68.9,"dl":222.1,"fh":26,"dh":47.7,"pad":8,"rootU":18,"rootV":33,"restU":179.3,"restV":212.8,"f":[664,268,84,52],"d":[112,0,238,95]},{"side":1,"i":2,"fl":70.4,"dl":165.9,"fh":26,"dh":38.7,"pad":8,"rootU":-8,"rootV":35,"restU":-4.6,"restV":226.5,"f":[0,339,86,52],"d":[224,184,181,77]},{"side":1,"i":3,"fl":63.6,"dl":177.1,"fh":26,"dh":33.9,"pad":8,"rootU":-35,"rootV":33,"restU":-192.1,"restV":159.0,"f":[88,339,79,52],"d":[168,268,193,67]},{"side":-1,"i":0,"fl":81.5,"dl":190.1,"fh":26,"dh":36.5,"pad":8,"rootU":25,"rootV":-27,"restU":205.6,"restV":-155.5,"f":[169,339,97,52],"d":[407,184,206,73]},{"side":-1,"i":1,"fl":90.0,"dl":196.6,"fh":26,"dh":43.4,"pad":8,"rootU":5,"rootV":-33,"restU":73.0,"restV":-259.8,"f":[268,339,106,52],"d":[352,0,212,86]},{"side":-1,"i":2,"fl":70.1,"dl":150.1,"fh":26,"dh":34.7,"pad":8,"rootU":-28,"rootV":-33,"restU":-117.0,"restV":-192.6,"f":[376,339,86,52],"d":[0,268,166,69]},{"side":-1,"i":3,"fl":50.3,"dl":208.2,"fh":26,"dh":31.0,"pad":8,"rootU":-42,"rootV":-20,"restU":-246.1,"restV":-93.9,"f":[464,339,66,52],"d":[363,268,224,61]}];                               // each leg: photo pieces + where it attaches / rests (photo pixels)

  const cv = document.createElement('canvas');
  Object.assign(cv.style, { position: 'fixed', inset: '0', width: '100%', height: '100%', zIndex: '5', pointerEvents: 'none' });
  cv.setAttribute('aria-hidden', 'true');
  document.body.appendChild(cv);
  const ctx = cv.getContext('2d');
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const rnd = (a, b) => a + Math.random() * (b - a);
  const turn = (to, from) => ((to - from + 3 * Math.PI) % (2 * Math.PI)) - Math.PI;
  let W, H, K0;                                        // K0 = screen px per photo px at SIZE 1
  const resize = () => {
    const d = Math.min(devicePixelRatio || 1, 2);
    W = innerWidth; H = innerHeight; K0 = clamp(Math.min(W, H) / 1100, .4, .9);
    cv.width = W * d; cv.height = H * d; ctx.setTransform(d, 0, 0, d, 0, 0);
  };
  addEventListener('resize', resize); resize();

  function makeSpider() {
    return {
      legs: LEGS.map(L => Object.assign({}, L, { g: (L.i + (L.side === 1 ? 0 : 1)) % 2, x: 0, y: 0, sx: 0, sy: 0, tx: 0, ty: 0, t: 1, dur: .1, lift: 0 })),
      bx: rnd(W * .1, W * .9), by: rnd(H * .1, H * .9), th: rnd(0, 6.283), speed: 0,
      tx: W / 2, ty: H / 2, rest: rnd(.2, 2.5), ready: false,
      size: rnd(.8, 1.25), pace: rnd(.8, 1.25),        // every spider is a little different
      D: rnd(.8, 1.05), mode: 'near', modeT: rnd(3, 9), Dfrom: 1, Dto: 1, trans: 0, K: 0.3
    };
  }
  const DMIN = .55, DMAX = 1.15;

  function newTarget(s) {                              // pick a spot well away from here
    const m = 110 * s.K;
    for (let n = 0; n < 8; n++) {
      s.tx = rnd(m, W - m); s.ty = rnd(m, H - m);
      if (Math.hypot(s.tx - s.bx, s.ty - s.by) > 230 * s.K) break;
    }
  }

  const vecs = s => ({ fx: Math.cos(s.th), fy: Math.sin(s.th), rx: -Math.sin(s.th), ry: Math.cos(s.th) });
  const at = (s, u, v, w) => ({ x: s.bx + w.fx * u * s.K + w.rx * v * s.K, y: s.by + w.fy * u * s.K + w.ry * v * s.K });
  function startStep(l, x, y, dur) { l.sx = l.x; l.sy = l.y; l.tx = x; l.ty = y; l.t = 0; l.dur = dur; }

  function updateLegs(s, dt, w) {
    const legs = s.legs, K = s.K;
    if (!s.ready) { legs.forEach(l => { const r = at(s, l.restU, l.restV, w); l.x = r.x; l.y = r.y; }); s.ready = true; }
    legs.forEach(l => {
      if (l.t < 1) {
        l.t = Math.min(1, l.t + dt / l.dur);
        const e = l.t * l.t * (3 - 2 * l.t);
        l.x = l.sx + (l.tx - l.sx) * e; l.y = l.sy + (l.ty - l.sy) * e; l.lift = Math.sin(Math.PI * l.t);
      } else l.lift = 0;
    });
    const busy = legs.find(l => l.t < 1), group = busy ? busy.g : -1;
    legs.forEach(l => {                                // step when the foot lags behind (two alternating groups of 4 legs)
      if (l.t < 1 || (group !== -1 && group !== l.g)) return;
      const r = at(s, l.restU, l.restV, w);
      if (Math.hypot(r.x - l.x, r.y - l.y) > 70 * K) startStep(l, r.x + w.fx * s.speed * .12, r.y + w.fy * s.speed * .12, s.speed > 40 ? .1 : .17);
    });
    if (s.speed < 10 && !busy && Math.random() < dt * 1.3) {   // creepy idle twitches
      const l = legs[Math.floor(Math.random() * 8)], r = at(s, l.restU, l.restV, w);
      startStep(l, r.x + rnd(-18, 18) * K, r.y + rnd(-18, 18) * K, .15);
    }
  }

  function piece(r, x, y, ang, K, half, pad) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(ang); ctx.scale(K, K);
    ctx.drawImage(ATLAS, r[0], r[1], r[2], r[3], -pad, -half, r[2], r[3]);
    ctx.restore();
  }

  function drawLeg(s, l, w) {
    const K = s.K, root = at(s, l.rootU, l.rootV, w), a = l.fl * K, b = l.dl * K;
    const dx = l.x - root.x, dy = l.y - root.y, d = Math.hypot(dx, dy) || 1;
    const dd = clamp(d, Math.abs(a - b) + 2, a + b - 1), base = Math.atan2(dy, dx);
    const A = Math.acos(clamp((a * a + dd * dd - b * b) / (2 * a * dd), -1, 1));
    const c1 = { x: root.x + a * Math.cos(base + A), y: root.y + a * Math.sin(base + A) };
    const c2 = { x: root.x + a * Math.cos(base - A), y: root.y + a * Math.sin(base - A) };
    const k = Math.hypot(c1.x - s.bx, c1.y - s.by) > Math.hypot(c2.x - s.bx, c2.y - s.by) ? c1 : c2;   // knee points outward
    const f = { x: root.x + dx / d * dd, y: root.y + dy / d * dd };
    const sc = K * (1 + .07 * l.lift);                                                                  // raised leg looks closer to you
    piece(l.f, root.x, root.y, Math.atan2(k.y - root.y, k.x - root.x), sc, l.fh, l.pad);
    piece(l.d, k.x, k.y, Math.atan2(f.y - k.y, f.x - k.x), sc, l.dh, l.pad);
  }

  function drawBody(s) {
    ctx.save(); ctx.translate(s.bx, s.by); ctx.rotate(s.th); ctx.scale(s.K, s.K); ctx.rotate(Math.PI / 2);
    ctx.drawImage(ATLAS, BODY.r[0], BODY.r[1], BODY.r[2], BODY.r[3], -BODY.ax, -BODY.ay, BODY.w, BODY.h);
    ctx.restore();
  }

  function update(s, dt) {
    if (DEPTH) {                                       // slowly drift a little nearer / farther
      s.modeT -= dt;
      if (s.mode === 'far' || s.mode === 'near') {
        if (s.modeT <= 0) { s.mode = s.mode === 'far' ? 'rising' : 'sinking'; s.trans = 0; s.Dfrom = s.D; s.Dto = s.mode === 'rising' ? rnd(1, DMAX) : rnd(DMIN, .75); }
      } else {
        s.trans += dt / rnd(1.6, 2.6);
        const e = Math.min(1, s.trans); s.D = s.Dfrom + (s.Dto - s.Dfrom) * (e * e * (3 - 2 * e));
        if (s.trans >= 1) { s.mode = s.mode === 'rising' ? 'near' : 'far'; s.modeT = rnd(4, 10); }
      }
    }
    s.K = K0 * SIZE * s.size * s.D;
    const K = s.K;

    // walking: turn on the spot first, then run straight; dart, freeze, twitch (no circling)
    if (s.rest > 0) {
      s.rest -= dt; s.speed *= Math.pow(.0004, dt);
      if (s.rest <= 0) newTarget(s);
    } else {
      const dx = s.tx - s.bx, dy = s.ty - s.by, dist = Math.hypot(dx, dy), err = turn(Math.atan2(dy, dx), s.th);
      s.th += clamp(err, -7 * dt, 7 * dt);
      const align = clamp(1 - Math.abs(err) / .6, 0, 1);
      s.speed += (rnd(240, 460) * Math.pow(K, .8) * 1.6 * s.pace * align - s.speed) * Math.min(1, dt * 8);
      s.bx += Math.cos(s.th) * s.speed * dt; s.by += Math.sin(s.th) * s.speed * dt;
      if (dist < 24 * K) s.rest = Math.random() < .25 ? rnd(.08, .3) : rnd(.6, 3);
    }
    const mg = 100 * K; s.bx = clamp(s.bx, mg, W - mg); s.by = clamp(s.by, mg, H - mg);
    updateLegs(s, dt, vecs(s));
  }

  function draw(s) {
    const w = vecs(s);
    ctx.globalAlpha = DEPTH ? .6 + .4 * clamp((s.D - DMIN) / (DMAX - DMIN), 0, 1) : 1;
    s.legs.slice().sort((p, q) => p.lift - q.lift).forEach(l => drawLeg(s, l, w));
    drawBody(s);
    ctx.globalAlpha = 1;
  }

  const spiders = Array.from({ length: COUNT }, makeSpider);
  let last = performance.now();
  function frame(now) {
    const dt = Math.min((now - last) / 1000, .05); last = now;
    ctx.clearRect(0, 0, W, H);
    spiders.forEach(s => update(s, dt));
    if (ATLAS.complete && ATLAS.naturalWidth) spiders.slice().sort((p, q) => p.D - q.D).forEach(draw);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
